transforms.code:
customProperty = "droppedData"
code = """<img id="""+self.custom.uuid+""" style='display:none' src='/favicon.ico' onload=\"
	const view = [...window.__client.page.views._data.values()].find(view => view.value.mountPath == this.parentNode.parentNode.parentNode.getAttributeNode('data-component-path').value.split('.')[0]).value;
	const uuid = view.custom.read('uuid');
	function ondrop(ev) {
		if (!view.custom.read('allowDrag')) return;
		ev.stopPropagation();
		ev.preventDefault();
		const draggedId = ev.dataTransfer.getData('text');
		const droppedId = this.parentNode.getAttribute('data-item-path');
		view.custom.write('droppedData', {'draggedId': draggedId, 'droppedId': droppedId});
	};
	function ondroproot(ev) {
		if (!view.custom.read('allowDrag')) return;
		ev.stopPropagation();
		ev.preventDefault();
		const draggedId = ev.dataTransfer.getData('text');
		view.custom.write('droppedData', {'draggedId': draggedId, 'droppedId': null});
	};
	function ondragstart(ev){
		if (!view.custom.read('allowDrag')) return;
		view.custom.write('droppedData', null);
		const nodePath =  this.parentNode.getAttribute('data-item-path');
		ev.dataTransfer.setData('text', nodePath);
	};
	function ondragover(ev){
		if (!view.custom.read('allowDrag')) return;
		ev.stopPropagation();
		ev.preventDefault();
	};
	const callbackTable = (mutationList, observer) => {
		document.querySelectorAll(`#draggableParent-${uuid} .tree-row.ia_treeComponent__node`).forEach((e, i) => {
			e.classList.remove('ry_tree__node--dragover');
			e.setAttribute('draggable',true);
			e.ondragstart = ondragstart;
			e.ondrop = ondrop;
			e.ondragover = ondragover;
		});	
	};
	const observerTable = new MutationObserver(callbackTable); 
	const tables = document.querySelectorAll(`#draggableParent-${uuid}`);
	tables.forEach(table => {
		observerTable.observe(table, { attributes: false, childList: true, subtree: true});
	});
	const trees = document.querySelectorAll(`.psc-draggableParent.tree`);
	trees.forEach(tree => {
		observerTable.observe(tree, { attributes: false, childList: true, subtree: true});
	});
	document.querySelectorAll(`#draggableParent-${uuid} .tree-row.ia_treeComponent__node`)
		.forEach((e, i) => {
			e.classList.remove('ry_tree__node--dragover');
			e.setAttribute('draggable',true);
			e.ondragstart = ondragstart;
			e.ondrop = ondrop;
			e.ondragover = ondragover;
		});
	document.querySelectorAll(`.psc-draggableParent.tree`)
		.forEach((e, i) => {
			e.classList.remove('ry_tree__node--dragover');
			e.ondrop = ondroproot;
			e.ondragover = ondragover;
		});
	\"></img>""".replace("\n", "").replace("\t", "")

return code


